{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The effects of waiting time for outpatient psychotherapeutic interventions on patientreported outcomes in adolescents and adults with eating disorders: a systematic review and meta-analysis",
      "reason": "The title explicitly includes the phrase 'a systematic review', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The effects of waiting time for outpatient psychotherapeutic interventions on patientreported outcomes in adolescents and adults with eating disorders: a systematic review and meta-analysis",
      "reason": "The title specifies the population ('adolescents and adults with eating disorders'), the exposure/intervention ('waiting time for outpatient psychotherapeutic interventions'), and the outcome ('patientreported outcomes'), providing key information about the main objective."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The effects of waiting time for outpatient psychotherapeutic interventions on patientreported outcomes in adolescents and adults with eating disorders: a systematic review and meta-analysis",
      "reason": "The title includes the supplementary information 'meta-analysis', indicating the analysis method used in the review."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Participants entered the waiting period with high EDE-Q Global Scores, ranging from 3.08 to 4.65 across studies.",
      "reason": "The manuscript describes the current state of knowledge about patient status while waiting (high baseline EDE-Q scores) and indicates burden persists, addressing important uncertainty about waiting effects."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_29",
      "quote": "These considerations inevitably resulted in a relatively small number of eligible studies. However, rather than indicating an overly narrow review scope, this primarily underscores the scarcity of comparable evidence on waiting time effects in EDs, particularly from a patient-centred perspective.",
      "reason": "The manuscript explains the importance and need for the review by identifying a scarcity of comparable evidence on waiting-time effects in eating disorders and motivating further research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_26",
      "quote": "Our findings align with previous meta-analyses in the context of social anxiety disorder and panic disorder [68, 69].",
      "reason": "The manuscript compares findings to prior meta-analyses in other disorders but does not explicitly identify, cite, or justify the need relative to prior systematic reviews or meta-analyses on the same topic in eating disorders; thus partially addresses the requirement."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review assesses effects of waiting time rather than evaluating a specific intervention's effects; no proposed mechanism of action for an intervention is described in the provided evidence, so the requirement for intervention mechanism is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context requiring a logic model; no logic model or hypothesised relationships between intervention components and outcomes are relevant in the provided evidence."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "'The research question 'What are the effects of waiting time for outpatient psychotherapeutic interventions on PROs in adolescents and adults with AN, BN, BED and OSFED' was formulated using the Population, Exposure, Comparator, Outcome (PECO) framework (Additional file 1).'",
      "reason": "The manuscript explicitly states the review research question addressing effects of waiting time on patient-reported outcomes in specified populations and notes it was formulated using a question-formulation framework (PECO)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "'The research question ... was formulated using the Population, Exposure, Comparator, Outcome (PECO) framework (Additional file 1).'",
      "reason": "For a review of intervention-related effects, the authors explicitly state they used the PECO framework (an appropriate variant of PICO) to formulate the research question, fulfilling the requirement to state planned comparisons using an appropriate variant."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were included if they used an empirical, quantitative design, either randomised or non-randomised, such as RCTs, clinical trials, quasi-experimental studies or cohort studies; involved adolescents (≥ 10 years, according to the World Health Organization [72] definition) and/or adults (≥ 18 years) with AN, BN, BED or OSFED, according to DSM or International Statistical Classification of Diseases and Related Health Problems (ICD) (research) criteria that were valid at the time of diagnosis, or who exceeded validated cut-off values in questionnaires or interviews based on DSM or ICD (research) criteria for AN, BN, BED or OSFED that are explicitly stated to be used as a proxy for full diagnosis. ... included a waiting period ≥ 4 weeks for the WLCG, no-treatment group or cohort of patients who ultimately received outpatient psychotherapy; reported ED-specific PROs, measured using the Children's Eating Attitudes Test (chEAT) [73], Eating Disorder Examination-Questionnaire (EDEQ) [74] or EDE-Q 6.0 [75], for all study groups separately; and reported these PROs for a minimum of two time points: (1) at or near the time of initial consultation, diagnostic workup, or study enrolment (baseline), and (2) at least once at a subsequent time point (i.e. at intervention start and/or at follow-up).",
      "reason": "The manuscript specifies detailed study characteristics used for eligibility: eligible study designs, age criteria, diagnostic criteria (DSM/ICD and proxies), minimum waiting period for controls, required PROM instruments and minimum timepoints."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included regardless of publication status. Both peer-reviewed and grey literature were considered. No restrictions were applied regarding publication year or language.",
      "reason": "The review explicitly states eligibility criteria for report characteristics: no restrictions on publication status, year, or language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement was found that distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported; retrieved evidence notes missing outcome reporting but does not document this specific distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "A within-group random-effects meta-analysis was performed assessing pre-post change scores of the EDE-Q Global Score (primary analysis) and EDE-Q subscales (secondary analyses).",
      "reason": "The synthesis groups are specified (within-group, pre-post changes in waitlist groups) and linked to the review objective/comparison (effects of waiting time on EDE-Q outcomes)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "During the work process, the eligibility criteria have been amended once to ensure precision, clarity, and reproducibility. Additionally, the eligible patient-reported outcome measures (PROMs) have been specified to enhance comparability between the individual studies. This specification was made in accordance with the ICHOM recommendations [33] to follow international consensus and ensure participation of persons with lived experience in the decision-making process. The amendments were made prior to data extraction and have been documented in version 2.0 of the registration record. Rationales for the exclusion criteria are provided in Additional file 3.",
      "reason": "The manuscript reports rationale(s) for notable restrictions (amendment to eligibility, specification of PROMs with ICHOM rationale) and indicates where fuller rationales for exclusions are documented."
    }
  ],
  "confidence": "75"
}

